// ============================================
// LOAD OR INITIALIZE STATE
// ============================================
const sessionId = $input.item.json.sessionId || `session_${Date.now()}`;
let state = $input.item.json.state;
const isTraining = $input.item.json.isTraining === true;
const userMessage = $input.item.json.message;
const feedback = $input.item.json.feedback; // optional

if (!state) {
  state = {
    session_id: sessionId,
    is_training: isTraining,
    current_intent: null,
    available_intents: ["search_flight", "book_flight", "cancel_booking", "fallback"],
    slots: {},
    action_results: [],
    conversation_memory: [],
    feedback_log: []
  };
}

// Append user message to memory
state.conversation_memory.push({ role: "user", content: userMessage });

// Keep only last 10 turns to avoid token overflow
if (state.conversation_memory.length > 20) {
  state.conversation_memory = state.conversation_memory.slice(-20);
}

return {
  sessionId,
  state,
  userMessage,
  isTraining,
  feedback
};

// ============================================
// BUILD RAG QUERY TEXT (for embedding)
// ============================================
const state = $input.item.json.state;
const lastTwoUserMessages = state.conversation_memory
  .filter(m => m.role === "user")
  .slice(-2)
  .map(m => m.content)
  .join(" ");

const queryText = `Current intent: ${state.current_intent || "none"}. User just said: ${lastTwoUserMessages}`;
return { queryText };

// ============================================
// CONVERT EMBEDDING TO PG VECTOR STRING
// ============================================
const embeddingArray = $input.item.json.data[0].embedding;
const vectorString = `[${embeddingArray.join(",")}]`;
return { vectorString };

// ============================================
// PREPARE INTENT SELECTOR PROMPT WITH RAG CONTEXT
// ============================================
const state = $input.item.json.state;
const userMessage = $input.item.json.userMessage;
const ragChunks = $input.item.json.ragChunks; // from previous node

const ragContextText = ragChunks.map(chunk => `- ${chunk.content}`).join("\n");

const systemPrompt = `You are an Intent Selector for a conversational assistant.

Available intents: ${state.available_intents.join(", ")}
Training mode: ${state.is_training}

RAG context (similar examples/rules):
${ragContextText}

Rules:
- If training mode is true and confidence in any available intent is < 0.7, you MAY propose a new intent.
- If training mode is false, you MUST choose ONLY from available intents. If confidence < 0.6, output intent = "fallback".
- Output valid JSON only.

Output format:
{
  "selected_intent": "string or null",
  "confidence": 0.0-1.0,
  "updated_slots": {},
  "action_request": { "action_name": "...", "params": {} },
  "new_intent_proposal": { "name": "string", "examples": ["..."] } // only if training & low conf
}`;

const userPrompt = `Conversation history (last 3 turns):\n${JSON.stringify(state.conversation_memory.slice(-3))}\n\nLatest user message: "${userMessage}"`;

return {
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt }
  ]
};

// ============================================
// PARSE INTENT + EXECUTE ACTION
// ============================================
const intentOutput = JSON.parse($input.item.json.choices[0].message.content);
let state = $input.item.json.state;
const isTraining = state.is_training;
const retrievedChunkIds = $input.item.json.ragChunks?.map(c => c.id) || [];

let actionResult = null;
let updatedState = { ...state };

// Handle low confidence & training mode
if (intentOutput.confidence < 0.7 && isTraining && intentOutput.new_intent_proposal) {
  updatedState.generated_intent = intentOutput.new_intent_proposal;
  updatedState.current_intent = "clarify_new_intent";
  actionResult = {
    type: "clarify",
    message: `Did you mean "${intentOutput.new_intent_proposal.name}"?`,
    proposal: intentOutput.new_intent_proposal
  };
} else if (intentOutput.confidence < 0.6 && !isTraining) {
  updatedState.current_intent = "fallback";
  actionResult = { type: "fallback", message: "I don't understand. Please rephrase." };
} else {
  // Normal intent
  updatedState.current_intent = intentOutput.selected_intent;
  updatedState.slots = { ...updatedState.slots, ...(intentOutput.updated_slots || {}) };

  const actionReq = intentOutput.action_request;
  if (actionReq) {
    // ---------- ACTION EXECUTOR (customizable) ----------
    if (actionReq.action_name === "search_flights") {
      // Simulate API call
      actionResult = {
        success: true,
        data: { flights: ["UA123", "AF456"], message: "Found 2 flights" }
      };
    } else if (actionReq.action_name === "book_flight") {
      actionResult = { success: true, data: { booking_id: "B123" } };
    } else if (actionReq.action_name === "cancel_booking") {
      actionResult = { success: true, data: { cancelled: true } };
    } else {
      actionResult = { success: false, error: `Unknown action: ${actionReq.action_name}` };
    }

    updatedState.action_results.push({
      action: actionReq.action_name,
      result: actionResult,
      timestamp: new Date().toISOString()
    });
  }
}

return {
  state: updatedState,
  actionResult,
  intentInfo: intentOutput,
  retrievedChunkIds,
  needClarification: actionResult?.type === "clarify" || actionResult?.type === "fallback"
};

// ============================================
// PREPARE RESPONSE AGENT PROMPT
// ============================================
const state = $input.item.json.state;
const actionResult = $input.item.json.actionResult;
const intentInfo = $input.item.json.intentInfo;
const userMessage = $input.item.json.userMessage;

const systemPrompt = `You are a helpful assistant.
Current intent: ${state.current_intent}
Last action result: ${JSON.stringify(actionResult)}
Training mode: ${state.is_training}
Available next intents: ${state.available_intents.join(", ")}

Instructions:
- Describe what action was executed and its result in natural language.
- If training mode and a new intent was proposed, ask the user for confirmation.
- If fallback, politely ask the user to rephrase or choose from available intents.
- Suggest next steps based on the current state.
- Do NOT output JSON – only natural language.`;

const userPrompt = `User said: "${userMessage}"`;

return {
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt }
  ]
};

// ============================================
// APPEND ASSISTANT RESPONSE TO STATE MEMORY
// ============================================
const assistantResponse = $input.item.json.choices[0].message.content;
let state = $input.item.json.state;

state.conversation_memory.push({ role: "assistant", content: assistantResponse });

return { state, assistantResponse };

// ============================================
// HANDLE FEEDBACK (if provided) FOR RETRIEVAL RANKING
// ============================================
const feedback = $input.item.json.feedback;
const sessionId = $input.item.json.sessionId;
const retrievedChunkIds = $input.item.json.retrievedChunkIds;

if (feedback && feedback.type && retrievedChunkIds && retrievedChunkIds.length > 0) {
  // For each chunk, we'll update counters (simulated – actual update would be in PostgreSQL node)
  // In a real workflow, you would loop over chunks and execute UPDATE queries.
  // This node returns data that can be used by a subsequent PostgreSQL node.
  const updates = retrievedChunkIds.map(chunkId => ({
    chunkId,
    feedbackType: feedback.type, // 'positive' or 'negative'
    sessionId
  }));
  return { updates, hasFeedback: true };
}
return { hasFeedback: false };
